				AssigneeAdd:     assigneeAdd,
				AssigneeRemove:  assigneeRemove,
				ReviewerAdd:     reviewerAdd,
				ReviewerRemove:  reviewerRemove,
				Type:            typeStr,
				TypeChanged:     cmd.Flags().Changed("type"),
